} Pair;

int cmp_desc(const void *a, const void *b) {
    double x = ((const Pair*)a)->t;
    double y = ((const Pair*)b)->t;
    if (x < y) return 1;
    if (x > y) return -1;
    return 0;
}

int main(void) {
    int n;
    ll L;
    if (scanf("%d %lld", &n, &L) != 2) return 0;

    Pair *a = (Pair*)malloc(sizeof(Pair) * n);
    for (int i = 0; i < n; i++) {
        scanf("%lld %lf", &a[i].v, &a[i].t);
    }

    qsort(a, n, sizeof(Pair), cmp_desc);

    double *ans = (double*)malloc(sizeof(double) * n);

    ll totalV = 0;
    double totalHeat = 0.0;

    int r = 0;              // first not fully taken item among hottest prefix
    ll usedFromR = 0;       // used volume from a[r]

    for (int day = 0; day < n; day++) {
        totalV += a[day].v;
        totalHeat += (double)a[day].v * a[day].t;

        if (totalV < L) {
            ans[day] = -1.0;   // impossible to have exactly L liters yet
            continue;
        }

        while (r < n) {
            ll avail = a[r].v - usedFromR;
            ll needRemove = totalV - L;
            if (needRemove <= 0) break;
            if (avail <= needRemove) {
                totalV -= avail;
                totalHeat -= (double)avail * a[r].t;
                r++;
                usedFromR = 0;
            } else {
                totalV -= needRemove;
                totalHeat -= (double)needRemove * a[r].t;
                usedFromR += needRemove;
                break;
            }
        }

        ans[day] = totalHeat / (double)L;
    }

    for (int i = 0; i < n; i++) {
        if (ans[i] < -0.5) {
            printf("-1\n");
        } else {
            printf("%.10f\n", ans[i]);
        }
    }

    free(a);
    free(ans);
    return 0;
}

