import java.io.*;
import java.util.*;

public class DamTemperature {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int L = Integer.parseInt(st.nextToken());
        int Q = Integer.parseInt(st.nextToken());

        // TreeMap: temperature -> volume (sorted by temperature ascending)
        TreeMap<Double, Double> map = new TreeMap<>();
        double totalVolume = 0;
        double totalHeat = 0;

        StringBuilder sb = new StringBuilder();

        for (int day = 0; day < Q; day++) {
            st = new StringTokenizer(br.readLine());
            double v = Double.parseDouble(st.nextToken());
            double t = Double.parseDouble(st.nextToken());

            // Add inflow
            map.put(t, map.getOrDefault(t, 0.0) + v);
            totalVolume += v;
            totalHeat += v * t;

            // If volume exceeds L, remove coldest water
            while (totalVolume > L) {
                double coldestTemp = map.firstKey();
                double coldVol = map.get(coldestTemp);
                double removeVol = Math.min(coldVol, totalVolume - L);

                if (coldVol == removeVol) {
                    map.remove(coldestTemp);
                } else {
                    map.put(coldestTemp, coldVol - removeVol);
                }

                totalVolume -= removeVol;
                totalHeat -= removeVol * coldestTemp;
            }

            // At noon, volume is exactly L
            double avgTemp = totalHeat / L;
            sb.append(String.format("%.10f%n", avgTemp));
        }

        System.out.print(sb.toString());
    }
}

