    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            double val = 0;
            while (c > ' ' && c != -1 && c != '.') {
                val = val * 10 + (c - '0');
                c = read();
            }
            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c > ' ' && c != -1) {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) Math.round(nextDouble());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        double L = fs.nextDouble();

        double[] a = new double[n];
        double[] t = new double[n];
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextDouble();
            t[i] = fs.nextDouble();
        }

        // DP over possible "best heat content" for exactly L liters at noon.
        // Let H_i be maximum total heat (volume * temperature) in the dam at noon of day i,
        // with exactly L liters.
        //
        // Suppose at noon of day i-1 we had L liters and heat H.
        // During night we may discharge any amount so that before next morning there are x liters left,
        // where x <= L - a[i]. Since we can discard arbitrarily, to maximize future temperature
        // we keep the hottest possible water. Because all water currently in the dam is perfectly mixed,
        // any kept part has the same temperature H / L. Thus keeping more only helps if that temperature
        // exceeds incoming temperature; otherwise keep as little as possible.
        //
        // Therefore recurrence on average temperature avg = H/L:
        // If avg >= t_i, keep maximum x = L - a_i.
        //   New heat = (L - a_i) * avg + a_i * t_i
        //            = (1 - a_i/L) * H + a_i * t_i
        // Else keep x = 0.
        //   New heat = a_i * t_i, but noon requires exactly L liters, so feasible only if a_i == L?
        //
        // However the statement implies each noon we need exactly L liters in the dam.
        // Hence morning inflow plus remaining water must equal L, so we must leave exactly L - a_i liters.
        // This is possible iff a_i <= L. Then:
        // H_i = ((L - a_i)/L) * H_{i-1} + a_i * t_i
        //
        // Starting from empty dam, day 1 noon can have exactly L liters only if a_1 == L.
        // More generally, since every day noon must have exactly L liters, previous noon is full too.
        // Thus the recurrence is forced.

        StringBuilder sb = new StringBuilder();
        double heat = 0.0;
        boolean possible = true;

        for (int i = 0; i < n; i++) {
            if (a[i] > L + 1e-12) {
                possible = false;
            }
            if (i == 0) {
                // Start from empty dam before day 1 morning.
                if (Math.abs(a[i] - L) > 1e-12) possible = false;
                heat = a[i] * t[i];
            } else {
                heat = ((L - a[i]) / L) * heat + a[i] * t[i];
            }

            if (!possible) {
                sb.append("-1\n");
            } else {
                sb.append(String.format(Locale.US, "%.10f%n", heat / L));
            }
        }

        System.out.print(sb.toString());
    }
}
